import{_ as o,l,o as e,c as s,v as t,p as d,x as r,d as n,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"时序数据库","description":"","frontmatter":{"title":"时序数据库","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/timeseries-db.md","filePath":"cs/timeseries-db.md","lastUpdated":1789023840000}'),E={name:"cs/timeseries-db.md"};function h(m,a,T,_,B,u){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="时序数据库" tabindex="-1">时序数据库 <a class="header-anchor" href="#时序数据库" aria-label="Permalink to &quot;时序数据库&quot;">​</a></h1><div class="epigraph"><p>主键是时间与序列 id：写追加、读范围、旧数据降采样或过期。压缩与分区按时间切开，B+ 点查不是第一路径。</p><footer>—— 据时序存储实践；LSM 与列压缩课的时间局部性；保留策略</footer></div><p><a href="/cs/graph-db">上一课</a>多跳爆炸。本课时间轴：指标、日志、传感器。缺口是数据生命周期：高写、范围扫、冷热分层。关系表也能存时间戳，但缺自动分片保留、Gorilla 一类压缩、乱序窗口（流课再讲）。本课存储引擎形状。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>序列：<code>(metric, tags, timestamp) → value</code>。写：几乎追加。读：最近窗口聚合。缺口是 <strong>tag 高基数</strong>（每个用户一序列）打爆倒排与内存索引。压缩：时间戳 delta、值 XOR（Facebook Gorilla 思路）。分区：按时间切，丢旧分区即 TTL，比 DELETE+vacuum 便宜——表分区课的时序特化。</p><p>乱序写：迟到点要插进已压缩块，代价高，常有乱序缓冲。与 LSM：按时间 SST，compaction 少跨时间。</p><p><span class="marginnote">Influx、Timescale、Prometheus TSDB 是产品。Gorilla 论文讲内存时序压缩。本课机制。不进金融微观结构（量化栏）。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>设计 tag 基数。降采样：物化 1m/1h 聚合，即物化视图刷新。查询下推聚合到存储。与 CDC：时序很少改历史，流式追加。</p><p>索引：倒排 tag → 序列 id，再沿时间列存扫。位图可标稀疏存在。</p>',10)),(e(),d(c,null,{default:r(()=>[p(i,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E8%BF%BD%E5%8A%A0%E5%86%99%22%5D%20--%3E%20PART%5B%22%E6%97%B6%E9%97%B4%E5%88%86%E5%8C%BA%22%5D%0A%20%20PART%20--%3E%20CMP%5B%22%E6%97%B6%E9%97%B4%2F%E5%80%BC%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20Q%5B%22%E8%8C%83%E5%9B%B4%E8%81%9A%E5%90%88%22%5D%20--%3E%20DOWN%5B%22%E4%B8%8B%E6%8E%A8%E5%88%B0%E5%9D%97%22%5D%0A%20%20TTL%5B%22%E8%BF%87%E6%9C%9F%22%5D%20--%3E%20DROP%5B%22%E4%B8%A2%E6%97%A7%E5%88%86%E5%8C%BA%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>HTAP：OLTP 元数据一行，时序另一引擎。校准：压缩后扫描极快，优化器若当行存会估错。WAL：可按块。副本：时间范围副本策略与热数据多副本。</p><p>与窗口流：存储是历史，流是进行中的窗口——后课衔接。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 ANN。也不把时序当量化交易撮合。向量库下一课：嵌入检索，时间可当过滤不是主模型。</p><p>后课默认：时间范围+TTL 用时序引擎或时间分区。向量数据库与 ANN：高维近邻，不是时间轴。</p><p>高基数 tag 会把时序库用成昂贵的文档库。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>时序以时间分区、压缩、TTL 为第一设计。</li><li>tag 基数与乱序写是主要税。</li><li>向量数据库与 ANN 下一课。</li><li>出处：Gorilla 压缩；LSM/分区课；TSDB 实践。</li></ul>',9))])}const D=o(E,[["render",h]]);export{f as __pageData,D as default};
